using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text.RegularExpressions;
using DhirDhar.Application.Localization;

namespace DhirDhar.Infrastructure.Localization;

public class LocalizationService : ILocalizationService
{
    private static string _globalCurrentLanguage = ResolveInitialLanguage();
    public static string GlobalCurrentLanguage => _globalCurrentLanguage;
    public static event EventHandler? GlobalLanguageChanged;

    private string _currentLanguage = ResolveInitialLanguage();

    public event EventHandler? LanguageChanged;

    public LocalizationService()
    {
        var initial = ResolveInitialLanguage();
        _currentLanguage = initial;
        _globalCurrentLanguage = initial;
        var culture = GetCulture();
        try
        {
            CultureInfo.CurrentCulture = culture;
            CultureInfo.CurrentUICulture = culture;
            System.Threading.Thread.CurrentThread.CurrentCulture = culture;
            System.Threading.Thread.CurrentThread.CurrentUICulture = culture;
        }
        catch { }
    }

    public static string ResolveInitialLanguage()
    {
        return LanguageConfigurationReader.SafeFallbackLanguage;
    }

